        { childId: "__rb21", fn: function () { return String((dma_pageContext.get("engAddr") ?? "")) + " " + String((dma_pageContext.get("engDtlAddr") ?? "")); } },
        { childId: "__rb23", fn: function () { return (dma_pageContext.get("ceoNm") ?? ""); } },
        { childId: "__rb25", fn: function () { return (dma_pageContext.get("hpage") ?? ""); } },
        { childId: "__rb27", fn: function () { return (dma_pageContext.get("telNo") ?? ""); } },
        { childId: "__rb29", fn: function () { return (dma_pageContext.get("acntclsTmp") ?? ""); } },
        { childId: "__rb31", fn: function () { return (dma_pageContext.get("leiNm") ?? ""); } },
        { childId: "__rb33", fn: function () { return (dma_pageContext.get("bzcondContn") ?? ""); } },
        { childId: "__rb35", fn: function () { return (dma_pageContext.get("isurIndContn") ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const list_stat_cd = (String(((dma_pageContext.get("list_stat_cd") ?? "")) === null ? '' : ((dma_pageContext.get("list_stat_cd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("list_stat_cd") ?? "")) === null ? '' : ((dma_pageContext.get("list_stat_cd") ?? ""))));
        if (list_stat_cd === "Y") {
            scwin.div_submit.setStyle("display", "none");
            scwin.div_close.setStyle("display", "");
            await $c.win.alert('현재의 발행기관은 주권상장법인입니다. \n주권상장법인은 발행기관변경신청을 받지 않습니다.');
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90702.onpageload' }); }
};

