 * @name check_form
 * @description check form 처리
 * @returns {void}
 * @hidden N
 */
scwin.check_form = function () {
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).go_modify();
    $c.win.closePopup();
};

/**
 * @method
 * @name self_close
 * @description self close 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.self_close = async function () {
    if (await $c.win.confirm("신청을 취소하시겠습니까?")) {
        $c.win.closePopup();
    }
};
